    let regex = if args.has_regex {
        Regex::new(&args.separator.item)
    } else {
        let escaped = regex::escape(&args.separator.item);
        Regex::new(&escaped)
    }
    .map_err(|e| ShellError::GenericError {
        error: "Error with regular expression".into(),
        msg: e.to_string(),
        span: Some(args.separator.span),
        help: None,
        inner: vec![],
    })?;

    input.flat_map(
        move |x| {
            split_column_helper(
                &x,
                &regex,
                &args.rest,
                args.collapse_empty,
                args.max_split,
                name_span,
            )
        },
        engine_state.signals(),
    )
}

fn split_column_helper(
    v: &Value,
    separator: &Regex,
    rest: &[Spanned<String>],
    collapse_empty: bool,
    max_split: Option<usize>,
    head: Span,
) -> Vec<Value> {
    let coerced = match v {
        Value::Int { val, .. } => {
            let text = val.to_string();
            Some(Cow::Owned(text))
        }
        Value::Float { val, .. } => {
            let text = val.to_string();
            Some(Cow::Owned(text))
        }
        Value::String { val, .. } => Some(Cow::Borrowed(val.as_str())),
        Value::Binary { val, .. } => match std::str::from_utf8(val) {
            Ok(text) => Some(Cow::Borrowed(text)),
            Err(_) => None,
        },
        Value::Date { val, .. } => {
            let text = val.to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
            Some(Cow::Owned(text))
        }
        _ => None,
    };

    if let Some(s) = coerced {
        let mut split_result: Vec<&str> = Vec::new();
        let pieces: Vec<&str> = match max_split {
            Some(max_split) => separator.splitn(s.as_ref(), max_split).collect(),
            None => separator.split(s.as_ref()).collect(),
        };
        for piece in pieces {
            if collapse_empty {
                if piece.is_empty() {
                    continue;
                }
            }
            split_result.push(piece);
        }

        let positional: Vec<String> = rest.iter().map(|column| column.item.clone()).collect();
        let piece_count = split_result.len();
        let named_count = positional.len();
        let capacity = if named_count == 0 {
            piece_count
        } else {
            named_count.min(piece_count)
        };
        let mut record = Record::with_capacity(capacity);

        if named_count == 0 {
            let mut idx = 0;
            while idx < piece_count {
                let column_name = format!("column{}", idx + 1);
                let cell = Value::string(split_result[idx], head);
                record.push(column_name, cell);
                idx += 1;
            }
        } else {
            let limit = named_count.min(piece_count);
            let mut idx = 0;
            while idx < limit {
                let column_name = positional[idx].clone();
                let cell = Value::string(split_result[idx], head);
                record.push(column_name, cell);
                idx += 1;
            }
        }

        vec![Value::record(record, head)]
    } else if let Value::Error { error, .. } = v {
        vec![Value::error(*error.clone(), head)]
    } else {
        let src_span = v.span();
        vec![Value::error(
            ShellError::PipelineMismatch {
                exp_input_type: "string".into(),
                dst_span: head,
                src_span,
            },
            src_span,
        )]
    }
}

